<?php
namespace App\Services;
use App\Models\{MediaAsset,MediaUsage}; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage;
class MediaService { public function upload(UploadedFile $file,string $folder='products'):MediaAsset{$path=$file->store('media/'.$folder.'/'.now()->format('Y/m'),'public');return MediaAsset::create(['disk'=>'public','path'=>$path,'filename'=>$file->getClientOriginalName(),'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'uploaded_by'=>auth()->id()]);} public function attach(MediaAsset $asset,object $model,?string $role=null):MediaUsage{return MediaUsage::updateOrCreate(['media_asset_id'=>$asset->id,'usable_type'=>$model::class,'usable_id'=>$model->getKey(),'role'=>$role]);} public function detach(MediaAsset $asset,object $model):void{$asset->usages()->where('usable_type',$model::class)->where('usable_id',$model->getKey())->delete();} public function delete(MediaAsset $asset):void{$asset->usages()->delete();Storage::disk($asset->disk)->delete($asset->path);$asset->delete();} }
